/**
 * Databricks Trigger Node - Version 1
 * Starts the workflow when Databricks job runs or pipeline updates change state
 */


export interface DatabricksTriggerV1Params {
/**
 * Time at which polling should occur
 * @default {"item":[{"mode":"everyMinute"}]}
 */
    pollTimes?: {
        /** Item
     */
    item?: Array<{
      /** How often to trigger.
       * @default everyDay
       */
      mode?: 'everyMinute' | 'everyHour' | 'everyDay' | 'everyWeek' | 'everyMonth' | 'everyX' | 'custom' | Expression<string>;
      /** The hour of the day to trigger (24h format)
       * @displayOptions.hide { mode: ["custom", "everyHour", "everyMinute", "everyX"] }
       * @default 14
       */
      hour?: number | Expression<number>;
      /** The minute past the hour to trigger (0-59)
       * @displayOptions.hide { mode: ["custom", "everyMinute", "everyX"] }
       * @default 0
       */
      minute?: number | Expression<number>;
      /** The day of the month to trigger
       * @displayOptions.show { mode: ["everyMonth"] }
       * @default 1
       */
      dayOfMonth?: number | Expression<number>;
      /** The weekday to trigger
       * @displayOptions.show { mode: ["everyWeek"] }
       * @default 1
       */
      weekday?: '1' | '2' | '3' | '4' | '5' | '6' | '0' | Expression<string>;
      /** Use custom cron expression. Values and ranges as follows:&lt;ul&gt;&lt;li&gt;Seconds: 0-59&lt;/li&gt;&lt;li&gt;Minutes: 0 - 59&lt;/li&gt;&lt;li&gt;Hours: 0 - 23&lt;/li&gt;&lt;li&gt;Day of Month: 1 - 31&lt;/li&gt;&lt;li&gt;Months: 0 - 11 (Jan - Dec)&lt;/li&gt;&lt;li&gt;Day of Week: 0 - 6 (Sun - Sat)&lt;/li&gt;&lt;/ul&gt;
       * @displayOptions.show { mode: ["custom"] }
       * @default * * * * * *
       */
      cronExpression?: string | Expression<string>;
      /** All how many X minutes/hours it should trigger
       * @displayOptions.show { mode: ["everyX"] }
       * @default 2
       */
      value?: number | Expression<number>;
      /** If it should trigger all X minutes or hours
       * @displayOptions.show { mode: ["everyX"] }
       * @default hours
       */
      unit?: 'minutes' | 'hours' | Expression<string>;
    }>;
  };
  authentication?: 'accessToken' | 'oAuth2' | Expression<string>;
  resource?: 'job' | 'pipeline';
/**
 * The job whose runs start the workflow
 * @searchListMethod getJobs
 * @displayOptions.show { resource: ["job"] }
 * @default {"mode":"list","value":""}
 */
    jobId?: { __rl: true; mode: 'list' | 'id' | 'url'; value: string; cachedResultName?: string };
/**
 * Events
 * @displayOptions.show { resource: ["job"] }
 * @default ["runFailed","runSucceeded"]
 */
    events?: Array<'runFailed' | 'runStarted' | 'runSucceeded'>;
/**
 * The pipeline whose updates start the workflow
 * @searchListMethod getPipelines
 * @displayOptions.show { resource: ["pipeline"] }
 * @default {"mode":"list","value":""}
 */
    pipelineId?: { __rl: true; mode: 'list' | 'id' | 'url'; value: string; cachedResultName?: string };
/**
 * Whether to return a simplified version of the response instead of the raw data
 * @default true
 */
    simplify?: boolean | Expression<boolean>;
}

export interface DatabricksTriggerV1Credentials {
  databricksApi: CredentialReference;
  databricksOAuth2Api: CredentialReference;
}

interface DatabricksTriggerV1NodeBase {
  type: 'n8n-nodes-base.databricksTrigger';
  version: 1;
  isTrigger: true;
}

export type DatabricksTriggerV1ParamsNode = DatabricksTriggerV1NodeBase & {
  config: NodeConfig<DatabricksTriggerV1Params> & { credentials?: DatabricksTriggerV1Credentials };
};

export type DatabricksTriggerV1Node = DatabricksTriggerV1ParamsNode;